def modular_sum(ary, m, n):
    # Create a dictionary to store remainders of each number modulo m
    rem = {}

    # Iterate through each number in the array
    for i in ary:
        # Calculate the remainder when the current number is divided by m
        rem[i % m] = rem.get(i % m, 0) + 1

    # Check if any remainder is divisible by n
    return any(rem[r] % n == 0 for r in rem)

