def sqrt_root( n ):
    # Check if the input is a perfect number
    if n < 0:
        return None  # Negative numbers cannot be perfect squares
    if n == 0:
        return 0  # 0 is a perfect square
    if n == 1:
        return 1  # 1 is a perfect square

    # Start from the smallest possible square root
    left = 1
    right = n

    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1

    return None  # No perfect square found

