import sys 
def min_coins(coins, m, V): 
    if (V == 0): 
        return 0
    res = sys.maxsize 
    for i in range(0, m): 
        if (coins[i] <= V): 
            sub_res = min_coins(coins, m, V-coins[i]) 
            if (sub_res != sys.maxsize and sub_res + 1 < res): 
                res = sub_res + 1  
    return res

def min_coins(coin_values, target_value, change):
    # Initialize a list to store the minimum number of coins needed
    coins_needed = [float('inf')] * (target_value + 1)
    coins_needed[0] = 0  # Base case: no coins needed for value 0

    # Iterate through each coin value
    for coin in coin_values:
        # Update the list with the minimum number of coins needed for each value
        for i in range(target_value + 1):
            if i >= coin:
                coins_needed[i] = min(coins_needed[i], coins_needed[i - coin] + 1)

    return coins_needed[target_value]

