import math 
def get_sum(n): 
	sum = 0
	i = 1
	while i <= (math.sqrt(n)): 
		if n%i == 0: 
			if n/i == i : 
				sum = sum + i 
			else: 
				sum = sum + i 
				sum = sum + (n / i ) 
		i = i + 1
	sum = sum - n 
	return sum
def check_abundant(n): 
	if (get_sum(n) > n): 
		return True
	else: 
		return False

def check_abundant( num ):
    # Check if the number is less than 2
    if num < 2:
        return False
    # Initialize sum to 0
    sum = 0
    # Iterate through each number from 1 to num-1
    for i in range(1, num):
        # If the number is divisible by i, add i to sum
        if num % i == 0:
            sum += i
    # Check if the sum is greater than the number itself
    if sum > num:
        return True
    else:
        return False

def check_abundant(Num):
    # Check if the number is less than 2
    if Num < 2:
        return False
    # Initialize sum to 0
    Sum = 0
    # Iterate through each number from 2 to the square root of the number
    for i in range(2, int(Num**0.5) + 1):
        # If the number is divisible by i, add i to the sum
        if Num % i == 0:
            Sum += i
    # Check if the sum is greater than the number itself
    if Sum > Num:
        return True
    else:
        return False

