    # Base case: if the start index is greater than or equal to the end index, return None
    if start >= end:
        return None

    # Calculate the middle index
    mid = (start + end) // 2

    # Check if the middle element is greater than the last element
    if ary[mid] > ary[end]:
        # If so, the maximum element is in the right half
        return find_Max(ary, mid + 1, end)
    else:
        # If not, the maximum element is in the left half
        return find_Max(ary, start, mid)

