def perfect_squares(a, b):
    lists=[]
    for i in range (a,b+1):
        j = 1;
        while j*j <= i:
            if j*j == i:
                 lists.append(i)  
            j = j+1
        i = i+1
    return lists

def perfect_squares(upper_limit, lower_limit):
    # Initialize an empty list to store perfect squares
    perfect_squares = []

    # Iterate through the range from lower_limit to upper_limit
    for num in range(lower_limit, upper_limit + 1):
        # Check if the square root of the number is an integer
        if int(num**0.5)**2 == num:
            # If it is, add the number to the list of perfect squares
            perfect_squares.append(num)

    return perfect_squares

