def binomial_Coeff(n,k): 
    C = [0] * (k + 1); 
    C[0] = 1; # nC0 is 1 
    for i in range(1,n + 1):  
        for j in range(min(i, k),0,-1): 
            C[j] = C[j] + C[j - 1]; 
    return C[k]; 
def sum_Of_product(n): 
    return binomial_Coeff(2 * n,n - 1);

def removezero_ip(ips):
    # Split the input string into a list of strings using '.' as the delimiter
    parts = ips.split('.')
    # Initialize an empty list to store the modified parts
    modified_parts = []
    # Iterate over each part in the list
    for part in parts:
        # Check if the part is not empty and starts with '0'
        if part and part[0] == '0':
            # If it does, append an empty string to the modified list
            modified_parts.append('')
        else:
            # Otherwise, append the part as is
            modified_parts.append(part)
    # Join the modified parts back into a single string with '.' as the delimiter
    return '.'.join(modified_parts)

