def find_kth(ary1, ary2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Iterate until k is reached
    while k > 0:
        # If i is out of bounds for ary1, use j from ary2
        if i >= len(ary1):
            j = j + len(ary2)
        # If j is out of bounds for ary2, use i from ary1
        elif j >= len(ary2):
            j = j + len(ary1)
        # Compare the elements at i and j
        if ary1[i] < ary2[j]:
            i += 1
        else:
            j += 1
        # Decrement k
        k -= 1

    # Return the kth element
    return ary1[i]

def find_kth(ary1, ary2, k, i, j):
    # Base case: if k is 0, return the first element of ary1
    if k == 0:
        return ary1[i]

    # Recursive case: find the k-th element in either ary1 or ary2
    if i < j:
        mid = (i + j) // 2
        if ary1[mid] > ary2[mid]:
            # If the middle element of ary1 is greater than the middle element of ary2, search in ary2
            return find_kth(ary2, ary1, k - mid - 1, mid + 1, j)
        else:
            # If the middle element of ary1 is less than or equal to the middle element of ary2, search in ary1
            return find_kth(ary1, ary2, k - mid - 1, i, mid)
    else:
        # If i is greater than j, return the last element of ary2
        return ary2[j]

# Test cases to verify the correctness of the function
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5, 4, 5) == 6
assert find_kth([100, 112, 256, 349, 770], [72, 86, 113, 119, 265, 445, 892], 5, 7, 7) == 256
assert find_kth([3, 4, 7, 8, 10], [2, 5, 9, 11], 5, 4, 6) == 8

