    else:
        # If i is greater than j, return the last element of ary2
        if i > j:
            return ary2[j]
        # Otherwise, find the kth element in the left half of ary1
        else:
            mid = (i + j) // 2
            # Recursively find the kth element in the right half of ary1
            return find_kth(ary1, ary2, k - 1, mid + 1, j)

