    if k == 0:
        return ary1[i]

    # Recursive case: find the k-th element in the merged array
    mid = (i + j) // 2
    if ary1[mid] < ary2[j]:
        # If the middle element of ary1 is less than the middle element of ary2, search in the right half
        return find_kth(ary1, ary2, k - mid - 1, mid + 1, j)
