def find_kth(ary1, ary2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Iterate until we have found the k-th element
    while i < len(ary1) and j < len(ary2):
        if ary1[i] < ary2[j]:
            i += 1
        else:
            j += 1

    # If i is equal to k, return ary1[i]
    if i == k:
        return ary1[i]
    # If j is equal to k, return ary2[j]
    elif j == k:
        return ary2[j]
    # If i is greater than k, return the element at ary1[i-k]
    elif i > k:
        return ary1[i - k]
    # If j is greater than k, return the element at ary2[j-k]
    else:
        return ary2[j - k]

