def find_kth(ary1, ary2, k, i, j):
    # Base case: if k is 0, return the first element of ary1
    if k == 0:
        return ary1[i]
    # Recursive case: find kth element in the remaining array
    else:
        # Check if the middle element of ary1 is greater than or equal to ary2
        if ary1[i] >= ary2[j]:
            # If so, find the kth element in ary1 excluding the middle element
            return find_kth(ary1, ary2, k - 1, i + 1, j)
        else:
            # If not, find the kth element in ary2 excluding the middle element
            return find_kth(ary1, ary2, k - 1, i, j - 1)

# Test cases
