def find_kth(ary1, ary2, k, i, j):
    # Base case: if k is 1, return the first element of ary1
    if k == 1:
        return ary1[i]
    # Recursive case: find the k-th element in the combined array
    mid = (i + j) // 2
    if ary1[mid] < ary2[j]:
        # If the middle element of ary1 is less than the last element of ary2, find in the right half
        return find_kth(ary1, ary2, k, mid + 1, j)
    else:
        # If the middle element of ary1 is greater than or equal to the last element of ary2, find in the left half
        return find_kth(ary1, ary2, k, i, mid)

# Test cases to verify the correctness of the function
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5, 4, 5) == 6
assert find_kth([100, 112, 256, 349, 770], [72, 86, 113, 119, 265, 445, 892], 5, 7, 7) == 256
assert find_kth([3, 4, 7, 8, 10], [2, 5, 9, 11], 5, 4, 6) == 8

def armstrong_number(number):
 sum = 0
 times = 0
 temp = number
 while temp > 0:
           times = times + 1
           temp = temp // 10
 temp = number
 while temp > 0:
           reminder = temp % 10
           sum = sum + (reminder ** times)
           temp //= 10
 if number == sum:
           return True
 else:
           return False

